import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { Link, useParams } from 'react-router-dom';

const PageContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const PageHeader = styled.div`
  margin-bottom: 35px;
  text-align: center;
  position: relative;
`;

const CategoryImage = styled.div`
  height: 300px;
  border-radius: 12px;
  overflow: hidden;
  position: relative;
  margin-bottom: 30px;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
  
  &:before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(to bottom, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.6) 100%);
    z-index: 1;
  }
  
  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
`;

const CategoryTitle = styled.h1`
  color: #333;
  margin-bottom: 15px;
  position: relative;
  display: inline-block;
  
  &:after {
    content: '';
    display: block;
    width: 80px;
    height: 3px;
    background: linear-gradient(90deg, #4CAF50, #FF9800);
    margin: 15px auto 0;
    border-radius: 3px;
  }
`;

const CategoryDescription = styled.p`
  color: #666;
  font-size: 1.2rem;
  max-width: 800px;
  margin: 0 auto 30px;
  line-height: 1.6;
`;

const FilterSection = styled.div`
  background-color: white;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.08);
  margin-bottom: 30px;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  
  @media (max-width: 768px) {
    flex-direction: column;
    align-items: stretch;
  }
`;

const FilterGroup = styled.div`
  display: flex;
  align-items: center;
  gap: 10px;
  
  @media (max-width: 768px) {
    justify-content: space-between;
  }
`;

const FilterLabel = styled.label`
  font-weight: 500;
  color: #333;
`;

const FilterSelect = styled.select`
  padding: 10px 15px;
  border: 1px solid #ddd;
  border-radius: 6px;
  font-size: 1rem;
  background-color: white;
  min-width: 150px;
  
  &:focus {
    outline: none;
    border-color: #4CAF50;
  }
`;

const SortSelect = styled(FilterSelect)``;

const RecipesCount = styled.div`
  font-size: 1.1rem;
  color: #666;
  
  span {
    font-weight: 600;
    color: #4CAF50;
  }
`;

const RecipesGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  margin-bottom: 40px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 576px) {
    grid-template-columns: 1fr;
  }
`;

const RecipeCard = styled.div`
  background-color: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease;
  
  &:hover {
    transform: translateY(-10px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
    
    img {
      transform: scale(1.08);
    }
  }
`;

const RecipeImage = styled.img`
  width: 100%;
  height: 220px;
  object-fit: cover;
  transition: transform 0.5s ease;
`;

const RecipeContent = styled.div`
  padding: 25px;
`;

const RecipeHeader = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
`;

const RecipeTitle = styled.h3`
  margin: 0;
  font-size: 1.3rem;
  color: #333;
`;

const RecipeDifficulty = styled.span`
  padding: 5px 10px;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 500;
  
  &.easy {
    background-color: #8BC34A;
    color: white;
  }
  
  &.medium {
    background-color: #FFC107;
    color: white;
  }
  
  &.hard {
    background-color: #FF5722;
    color: white;
  }
`;

const RecipeMeta = styled.div`
  display: flex;
  gap: 15px;
  margin-bottom: 15px;
  color: #666;
  font-size: 0.9rem;
  
  span {
    display: flex;
    align-items: center;
    gap: 5px;
  }
`;

const RecipeDescription = styled.p`
  color: #666;
  margin-bottom: 15px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
`;

const RecipePrice = styled.div`
  font-weight: bold;
  color: #4CAF50;
  font-size: 1.1rem;
  margin-top: 15px;
  padding-top: 15px;
  border-top: 1px solid #f0f0f0;
`;

const ViewRecipeButton = styled(Link)`
  display: block;
  background-color: #4CAF50;
  color: white;
  text-align: center;
  text-decoration: none;
  padding: 12px 0;
  border-radius: 6px;
  font-weight: 600;
  margin-top: 15px;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #45a049;
    transform: translateY(-3px);
  }
`;

const Pagination = styled.div`
  display: flex;
  justify-content: center;
  margin-top: 50px;
  gap: 10px;
`;

const PageButton = styled.button`
  background-color: ${props => props.active ? '#4CAF50' : 'white'};
  color: ${props => props.active ? 'white' : '#333'};
  border: ${props => props.active ? 'none' : '1px solid #ddd'};
  border-radius: 4px;
  padding: 8px 16px;
  cursor: pointer;
  
  &:hover {
    background-color: ${props => props.active ? '#45a049' : '#f5f5f5'};
  }
  
  &:disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }
`;

const NoRecipesFound = styled.div`
  text-align: center;
  padding: 50px 0;
  color: #666;
  
  h3 {
    color: #333;
    margin-bottom: 15px;
  }
  
  p {
    max-width: 500px;
    margin: 0 auto;
  }
`;

const CategoryPage = () => {
  const { categoryId } = useParams();
  const [recipes, setRecipes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [sort, setSort] = useState('newest');
  const [currentPage, setCurrentPage] = useState(1);
  const recipesPerPage = 9;
  
  // Kategori verileri
  const categories = {
    'ana-yemekler': {
      id: 'ana-yemekler',
      title: 'Ana Yemekler',
      image: 'https://images.unsplash.com/photo-1518779578993-ec3579fee39f?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'Ev yapımı lezzetli ana yemek tarifleri ile sofralarınızı zenginleştirin. En ekonomik şekilde en lezzetli ana yemekleri pişirin.'
    },
    'corbalar': {
      id: 'corbalar',
      title: 'Çorbalar',
      image: 'https://images.unsplash.com/photo-1503767849114-976b67568b02?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'Sıcacık, besleyici ve ekonomik çorba tarifleri. Kış aylarının vazgeçilmezi çorbalar için en uygun maliyetli tarifler.'
    },
    'tatlilar': {
      id: 'tatlilar',
      title: 'Tatlılar',
      image: 'https://images.unsplash.com/photo-1551024506-0bccd828d307?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'Ağzınızı tatlandıracak, misafirlerinizi etkileyecek ekonomik ve lezzetli ev yapımı tatlı tarifleri.'
    },
    'salatalar': {
      id: 'salatalar',
      title: 'Salatalar',
      image: 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'Sağlıklı, besleyici ve ekonomik salata tarifleri. Ana yemeklerin yanına veya tek başına tüketebileceğiniz lezzetli salatalar.'
    },
    'kahvaltilik': {
      id: 'kahvaltilik',
      title: 'Kahvaltılık',
      image: 'https://images.unsplash.com/photo-1533920379810-6bedac9e6212?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'Güne enerjik başlamanızı sağlayacak, ekonomik ve doyurucu kahvaltılık tarifleri.'
    },
    'atistirmaliklar': {
      id: 'atistirmaliklar',
      title: 'Atıştırmalıklar',
      image: 'https://images.unsplash.com/photo-1541529086526-db283c563270?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'Film izlerken, misafir ağırlarken veya çay saatlerinde keyifle tüketebileceğiniz ekonomik atıştırmalık tarifleri.'
    },
    'icecekler': {
      id: 'icecekler',
      title: 'İçecekler',
      image: 'https://images.unsplash.com/photo-1544145945-f90425340c7e?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'Serinleten, ferahlatan ve içinizi ısıtan içecek tarifleri. Ev yapımı ekonomik ve sağlıklı içecekler.'
    },
    'dunya-mutfagi': {
      id: 'dunya-mutfagi',
      title: 'Dünya Mutfağı',
      image: 'https://images.unsplash.com/photo-1455619452474-d2be8b1e70cd?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      description: 'İtalyan, Meksika, Çin, Hint ve daha pek çok dünya mutfağından ekonomik ve lezzetli tarifler.'
    }
  };

  // Seçilen kategori
  const selectedCategory = categories[categoryId];
  
  // Örnek tarif verileri
  const exampleRecipes = [
    {
      id: 1,
      title: 'Ev Yapımı Lazanya',
      image: 'https://images.unsplash.com/photo-1574894709920-11b28e7367e3?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'medium',
      time: '45 dk',
      servings: '4-6 kişilik',
      description: 'Lezzetli ve doyurucu ev yapımı lazanya. İtalyan mutfağının bu klasik lezzeti herkesi memnun edecek.',
      price: '₺120',
      categories: ['ana-yemekler', 'dunya-mutfagi'],
      author: 'Ayşe Yılmaz',
      date: '2023-03-15'
    },
    {
      id: 2,
      title: 'Köfte Patates',
      image: 'https://images.unsplash.com/photo-1529042410759-befb1204b468?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'easy',
      time: '30 dk',
      servings: '4 kişilik',
      description: 'Yer sofraların vazgeçilmezi, pratik ve lezzetli bir tarif. Çocukların en sevdiği yemeklerden biri.',
      price: '₺85',
      categories: ['ana-yemekler'],
      author: 'Mehmet Demir',
      date: '2023-03-10'
    },
    {
      id: 3,
      title: 'Sebzeli Makarna',
      image: 'https://images.unsplash.com/photo-1473093226795-af9932fe5856?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'easy',
      time: '20 dk',
      servings: '2 kişilik',
      description: 'Sağlıklı ve hafif bir makarna alternatifi. Taze sebzelerle hazırlanmış, lezzetli bir öğün.',
      price: '₺60',
      categories: ['ana-yemekler', 'vejetaryen'],
      author: 'Zeynep Kaya',
      date: '2023-03-05'
    },
    {
      id: 4,
      title: 'Tandır Kebabı',
      image: 'https://images.unsplash.com/photo-1611143669185-af224c5e3252?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'hard',
      time: '3 saat',
      servings: '6-8 kişilik',
      description: 'Geleneksel tandır fırınında pişirilmiş, yumuşacık ve sulu et. Özel günlerin vazgeçilmez lezzeti.',
      price: '₺220',
      categories: ['ana-yemekler'],
      author: 'Ali Şahin',
      date: '2023-02-28'
    },
    {
      id: 5,
      title: 'Mercimek Çorbası',
      image: 'https://images.unsplash.com/photo-1547592166-23ac45744acd?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'easy',
      time: '25 dk',
      servings: '4 kişilik',
      description: 'Türk mutfağının vazgeçilmez çorbası. Besleyici ve ekonomik bir seçenek.',
      price: '₺30',
      categories: ['corbalar'],
      author: 'Fatma Yılmaz',
      date: '2023-03-20'
    },
    {
      id: 6,
      title: 'Kremalı Mantar Çorbası',
      image: 'https://images.unsplash.com/photo-1541095441899-5d96a6da10b8?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'medium',
      time: '30 dk',
      servings: '4 kişilik',
      description: 'Kremsi dokusu ve zengin mantar aromasıyla damaklarda iz bırakan nefis bir çorba.',
      price: '₺45',
      categories: ['corbalar'],
      author: 'Selin Yıldız',
      date: '2023-03-18'
    },
    {
      id: 7,
      title: 'Çikolatalı Brownie',
      image: 'https://images.unsplash.com/photo-1564355808539-22fda35bed7e?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'medium',
      time: '35 dk',
      servings: '8 dilim',
      description: 'Dışı çıtır içi yumuşacık, bol çikolatalı brownie. Tatlı krizlerinin kurtarıcısı.',
      price: '₺70',
      categories: ['tatlilar'],
      author: 'Selin Yıldız',
      date: '2023-03-12'
    },
    {
      id: 8,
      title: 'Karışık Meyveli Yoğurt',
      image: 'https://images.unsplash.com/photo-1505253758473-96b7015fcd40?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'easy',
      time: '10 dk',
      servings: '2 kişilik',
      description: 'Taze meyveler ve yoğurtla hazırlanan sağlıklı ve ferahlatıcı bir ara öğün.',
      price: '₺40',
      categories: ['tatlilar', 'atistirmaliklar'],
      author: 'Deniz Kaya',
      date: '2023-03-22'
    }
  ];
  
  useEffect(() => {
    // Burada API'den kategoriye göre tarifleri çekebilirsiniz
    setLoading(true);
    
    // Şimdilik örnek verilerle çalışıyoruz
    setTimeout(() => {
      const filteredRecipes = exampleRecipes.filter(recipe => 
        recipe.categories.includes(categoryId)
      );
      
      setRecipes(filteredRecipes);
      setLoading(false);
    }, 500);
  }, [categoryId]);
  
  // Zorluk filtrelemesi
  const handleFilterChange = (e) => {
    setFilter(e.target.value);
    setCurrentPage(1);
  };
  
  // Sıralama
  const handleSortChange = (e) => {
    setSort(e.target.value);
    setCurrentPage(1);
  };
  
  // Zorluk seviyesine göre CSS sınıfı
  const getDifficultyClass = (difficulty) => {
    switch (difficulty) {
      case 'easy':
        return 'easy';
      case 'medium':
        return 'medium';
      case 'hard':
        return 'hard';
      default:
        return '';
    }
  };
  
  // Zorluk seviyesinin Türkçe karşılığı
  const getDifficultyText = (difficulty) => {
    switch (difficulty) {
      case 'easy':
        return 'Kolay';
      case 'medium':
        return 'Orta';
      case 'hard':
        return 'Zor';
      default:
        return '';
    }
  };
  
  // Filtreleme ve sıralama uygulama
  let filteredRecipes = [...recipes];
  
  // Zorluk filtrelemesi
  if (filter !== 'all') {
    filteredRecipes = filteredRecipes.filter(recipe => recipe.difficulty === filter);
  }
  
  // Sıralama
  switch (sort) {
    case 'newest':
      filteredRecipes.sort((a, b) => new Date(b.date) - new Date(a.date));
      break;
    case 'oldest':
      filteredRecipes.sort((a, b) => new Date(a.date) - new Date(b.date));
      break;
    case 'price-low':
      filteredRecipes.sort((a, b) => parseFloat(a.price.replace('₺', '')) - parseFloat(b.price.replace('₺', '')));
      break;
    case 'price-high':
      filteredRecipes.sort((a, b) => parseFloat(b.price.replace('₺', '')) - parseFloat(a.price.replace('₺', '')));
      break;
    default:
      break;
  }
  
  // Sayfalama
  const indexOfLastRecipe = currentPage * recipesPerPage;
  const indexOfFirstRecipe = indexOfLastRecipe - recipesPerPage;
  const currentRecipes = filteredRecipes.slice(indexOfFirstRecipe, indexOfLastRecipe);
  const totalPages = Math.ceil(filteredRecipes.length / recipesPerPage);
  
  // Sayfa değiştirme
  const paginate = (pageNumber) => setCurrentPage(pageNumber);
  
  if (!selectedCategory) {
    return (
      <PageContainer>
        <NoRecipesFound>
          <h3>Kategori Bulunamadı</h3>
          <p>Aradığınız kategori mevcut değil. Lütfen geçerli bir kategori seçin.</p>
        </NoRecipesFound>
      </PageContainer>
    );
  }
  
  return (
    <PageContainer>
      <PageHeader>
        <CategoryImage>
          <img src={selectedCategory.image} alt={selectedCategory.title} />
        </CategoryImage>
        <CategoryTitle>{selectedCategory.title}</CategoryTitle>
        <CategoryDescription>{selectedCategory.description}</CategoryDescription>
      </PageHeader>
      
      <FilterSection>
        <RecipesCount>
          <span>{filteredRecipes.length}</span> tarif bulundu
        </RecipesCount>
        
        <FilterGroup>
          <FilterLabel htmlFor="difficulty">Zorluk:</FilterLabel>
          <FilterSelect 
            id="difficulty"
            value={filter}
            onChange={handleFilterChange}
          >
            <option value="all">Tümü</option>
            <option value="easy">Kolay</option>
            <option value="medium">Orta</option>
            <option value="hard">Zor</option>
          </FilterSelect>
        </FilterGroup>
        
        <FilterGroup>
          <FilterLabel htmlFor="sort">Sırala:</FilterLabel>
          <SortSelect 
            id="sort"
            value={sort}
            onChange={handleSortChange}
          >
            <option value="newest">En Yeni</option>
            <option value="oldest">En Eski</option>
            <option value="price-low">Fiyat: Düşükten Yükseğe</option>
            <option value="price-high">Fiyat: Yüksekten Düşüğe</option>
          </SortSelect>
        </FilterGroup>
      </FilterSection>
      
      {loading ? (
        <div>Yükleniyor...</div>
      ) : currentRecipes.length > 0 ? (
        <>
          <RecipesGrid>
            {currentRecipes.map(recipe => (
              <RecipeCard key={recipe.id}>
                <RecipeImage src={recipe.image} alt={recipe.title} />
                <RecipeContent>
                  <RecipeHeader>
                    <RecipeTitle>{recipe.title}</RecipeTitle>
                    <RecipeDifficulty className={getDifficultyClass(recipe.difficulty)}>
                      {getDifficultyText(recipe.difficulty)}
                    </RecipeDifficulty>
                  </RecipeHeader>
                  
                  <RecipeMeta>
                    <span>⏱️ {recipe.time}</span>
                    <span>👥 {recipe.servings}</span>
                  </RecipeMeta>
                  
                  <RecipeDescription>{recipe.description}</RecipeDescription>
                  
                  <RecipePrice>Tahmini Maliyet: {recipe.price}</RecipePrice>
                  
                  <ViewRecipeButton to={`/recipes/${recipe.id}`}>
                    Tarifi Görüntüle
                  </ViewRecipeButton>
                </RecipeContent>
              </RecipeCard>
            ))}
          </RecipesGrid>
          
          {totalPages > 1 && (
            <Pagination>
              <PageButton 
                disabled={currentPage === 1}
                onClick={() => paginate(currentPage - 1)}
              >
                &laquo; Önceki
              </PageButton>
              
              {[...Array(totalPages).keys()].map(number => (
                <PageButton 
                  key={number + 1}
                  active={currentPage === number + 1}
                  onClick={() => paginate(number + 1)}
                >
                  {number + 1}
                </PageButton>
              ))}
              
              <PageButton 
                disabled={currentPage === totalPages}
                onClick={() => paginate(currentPage + 1)}
              >
                Sonraki &raquo;
              </PageButton>
            </Pagination>
          )}
        </>
      ) : (
        <NoRecipesFound>
          <h3>Tarif Bulunamadı</h3>
          <p>Seçtiğiniz filtrelere uygun tarif bulunamadı. Lütfen farklı filtreler deneyin.</p>
        </NoRecipesFound>
      )}
    </PageContainer>
  );
};

export default CategoryPage;
